css:
/* Maple's Bramble Cottage (round 6) by kolache.
   One idea: a recipe journal on a sunlit kitchen counter. Day = linen and morning light,
   night = a lamplit walnut kitchen. Fraunces (soft serif) for headings and names, Nunito for text.
   Signature: one sage running stitch (the same stitch on cards, dialogs and Home) and a pressed
   sprig on the newest reply. Pictures live in meta.images (theme:...). */

:root{
  --mari-tokens-version:1;
  --mari-font-ui:"Maple Nunito",Nunito,ui-rounded,system-ui,sans-serif;
  --mari-font-chat:"Maple Nunito",Nunito,ui-rounded,system-ui,sans-serif;
  --mari-font-heading:"Maple Fraunces",Fraunces,Georgia,serif;
  --mari-chat-font-size:17px;
  --maple-measure:33.5rem; /* the reading column: about 70 characters a line at 17px Nunito */
  --mari-chat-line-height:1.68;
  --mari-dialogue-weight:500;
  --mari-message-measure:68ch;
  --mari-paragraph-gap:.8em;
  --mari-pinned-speaker:on;
  --mari-focus-frame-outset:19px;
  --radius:14px;
  --mari-text-outline:0;
  --mari-msg-head-rule:none;
  --mari-composer-placeholder:"write a little something…";
  --mari-app-backdrop-position:center bottom;
  --mari-top-bar-plate-radius:999px;
  --mari-home-widget-radius:22px;
  --mari-home-widget-border:transparent;
  --mari-home-widget-border-width:0px;
  --mari-home-widget-title-font:"Maple Fraunces",Georgia,serif;
  --mari-home-widget-title-size:1.5rem;
  --mari-home-widget-eyebrow-size:.74rem;
  --mari-home-widget-text-size:.95rem;
  --mari-home-art:none;
  --mari-icon-send:url("theme:icon-send.webp");
  /* journal language */
  --maple-r-lg:22px;--maple-r-md:14px;--maple-r-sm:10px;
  --maple-stitch:url("theme:frame-9slice.webp");
  --maple-paper:url("theme:paper-tile.webp");
}

/* ───────── Day: linen and morning light ───────── */
:root[data-theme="light"]{
  --maple-ink:#4A3B32;--maple-muted:#76655A;--maple-rose:#A65D58;--maple-sage:#5F7B5A;--maple-honey:#B9873A;
  --maple-paper-c:#FFFDF7;--maple-linen:#FBF6EC;--maple-blush:#F6E1DC;
  --maple-shadow:0 1px 2px rgb(110 80 55/.07),0 6px 18px rgb(110 80 55/.09);
  --maple-shadow-lg:0 2px 6px rgb(110 80 55/.08),0 18px 40px rgb(110 80 55/.14);
  --background:#FBF6EC;--foreground:#4A3B32;
  --card:rgb(255 253 247/.95);--card-foreground:#4A3B32;--popover:#FFFDF7;--popover-foreground:#4A3B32;
  --primary:#A65D58;--primary-foreground:#FFFDF7;--ring:#A65D58;
  --secondary:#EEF0E4;--secondary-foreground:#4A3B32;
  --muted:#F3EDE0;--muted-foreground:#76655A;
  --accent:#F6E1DC;--accent-foreground:#7E4440;
  --destructive:#B24A3E;
  --border:rgb(125 100 80/.16);--input:rgb(125 100 80/.22);
  --sidebar:rgb(247 243 232/.90);--sidebar-foreground:#4A3B32;--sidebar-border:rgb(125 100 80/.12);
  --sidebar-accent:#F6E1DC;--sidebar-accent-foreground:#7E4440;
  --ov-line:rgb(125 100 80/.14);--ov-text:#4A3B32;--ov-muted:#76655A;--ov-dim:#8F7E71;--ov-accent:#A65D58;
  --ov-hover:rgb(166 93 88/.08);--ov-active-bg:rgb(166 93 88/.14);
  --mari-selected-tint:#A65D58;
  --ov-mode-conversation:#5F7B5A;--ov-mode-roleplay:#A65D58;--ov-mode-game:#9C7430;
  --mari-mode-conversation:#5F7B5A;--mari-mode-roleplay:#A65D58;--mari-mode-game:#9C7430;
  --mari-home-pink:#C98B85;--mari-home-violet:#9A8BB0;
  --mari-status-online:#4D6B47;--mari-status-idle:#C9A04F;--mari-status-dnd:#B9665F;--mari-status-offline:#A99A8C;
  --mari-gauge-ok:#6E8F68;--mari-gauge-warn:#C9A04F;--mari-gauge-danger:#B24A3E;
  --mari-scrim:rgb(90 70 55/.28);
  --mari-user-avatar-placeholder:linear-gradient(135deg,#DCE6D3,#93AE8E);
  --mari-art-saturation-1:24%;--mari-art-lightness-1:86%;--mari-art-saturation-2:22%;--mari-art-lightness-2:76%;
  --mari-focus-ring-color:#A65D58;
  --mari-chat-resolved-text:#4A3B32;
  --mari-dialogue-color:#8E4E4A;
  --mari-app-backdrop:url("theme:backdrop-day.webp");
  --mari-top-bar-bg:url("theme:topbar-strip.webp") left bottom / auto 100% repeat-x,#F6EEDD;
  --mari-top-bar-plate:rgb(255 253 247/.92);
  --mari-page-veil:rgb(251 246 236/.90);
  --mari-home-wash:rgb(251 246 236/.35);
  --mari-home-widget-bg:rgb(255 253 247/.94);
  --mari-home-widget-title-color:#4A3B32;
  --mari-home-widget-eyebrow-color:#5F7B5A;
  --mari-home-widget-muted:#76655A;
  --marinara-conversation-gradient-from:transparent;--marinara-conversation-gradient-to:transparent;
}

/* ───────── Night: lamplit walnut kitchen ───────── */
:root[data-theme="dark"]{
  --maple-ink:#F3E9DA;--maple-muted:#CDBBA6;--maple-rose:#EBB0A7;--maple-sage:#B3C9A9;--maple-honey:#E8B96A;
  --maple-paper-c:#3A302A;--maple-linen:#2B2320;--maple-blush:#5A3F3A;
  --maple-shadow:0 1px 2px rgb(10 6 4/.25),0 8px 22px rgb(10 6 4/.30);
  --maple-shadow-lg:0 2px 6px rgb(10 6 4/.3),0 22px 48px rgb(10 6 4/.42);
  --background:#2B2320;--foreground:#F3E9DA;
  --card:rgb(58 48 42/.95);--card-foreground:#F3E9DA;--popover:#3A302A;--popover-foreground:#F3E9DA;
  --primary:#EBB0A7;--primary-foreground:#2B2320;--ring:#EBB0A7;
  --secondary:#463A33;--secondary-foreground:#F3E9DA;
  --muted:#40352F;--muted-foreground:#CDBBA6;
  --accent:#55403A;--accent-foreground:#F6D7CF;
  --destructive:#E2877A;
  --border:rgb(243 233 218/.13);--input:rgb(243 233 218/.18);
  --sidebar:rgb(40 32 29/.92);--sidebar-foreground:#F3E9DA;--sidebar-border:rgb(243 233 218/.08);
  --sidebar-accent:#4A3A34;--sidebar-accent-foreground:#F6D7CF;
  --ov-line:rgb(243 233 218/.12);--ov-text:#F3E9DA;--ov-muted:#CDBBA6;--ov-dim:#A8957F;--ov-accent:#EBB0A7;
  --ov-hover:rgb(235 176 167/.09);--ov-active-bg:rgb(235 176 167/.16);
  --mari-selected-tint:#EBB0A7;
  --ov-mode-conversation:#B3C9A9;--ov-mode-roleplay:#EBB0A7;--ov-mode-game:#E8B96A;
  --mari-mode-conversation:#B3C9A9;--mari-mode-roleplay:#EBB0A7;--mari-mode-game:#E8B96A;
  --mari-home-pink:#EBB0A7;--mari-home-violet:#C9B8DA;
  --mari-status-online:#A9C79E;--mari-status-idle:#E8B96A;--mari-status-dnd:#E2877A;--mari-status-offline:#8F7E71;
  --mari-gauge-ok:#A9C79E;--mari-gauge-warn:#E8B96A;--mari-gauge-danger:#E2877A;
  --mari-scrim:rgb(20 14 11/.5);
  --mari-user-avatar-placeholder:linear-gradient(135deg,#7E9478,#4D5F49);
  --mari-art-saturation-1:16%;--mari-art-lightness-1:38%;--mari-art-saturation-2:14%;--mari-art-lightness-2:28%;
  --mari-focus-ring-color:#F2C6BE;
  --mari-chat-resolved-text:#F3E9DA;
  --mari-dialogue-color:#F2C2B9;
  --mari-app-backdrop:url("theme:backdrop-night.webp");
  --mari-top-bar-bg:linear-gradient(rgb(43 35 32/.80),rgb(43 35 32/.80)),url("theme:topbar-strip.webp") left bottom / auto 100% repeat-x,#2B2320;
  --mari-top-bar-plate:rgb(58 48 42/.94);
  --mari-page-veil:rgb(43 35 32/.92);
  --mari-home-wash:rgb(43 35 32/.35);
  --mari-home-widget-bg:rgb(58 48 42/.94);
  --mari-home-widget-title-color:#F3E9DA;
  --mari-home-widget-eyebrow-color:#B3C9A9;
  --mari-home-widget-muted:#CDBBA6;
  --maple-paper:url("theme:paper-tile-night.webp");
  /* lamplight: a warm pool top-left and soft corners, no particles over the text */
  --mari-ambient:radial-gradient(ellipse 60% 50% at 18% 0%,rgb(232 185 106/.10),transparent 70%),radial-gradient(ellipse 120% 90% at 50% 45%,transparent 60%,rgb(18 11 8/.30) 100%);
  --marinara-conversation-gradient-from:transparent;--marinara-conversation-gradient-to:transparent;
}

/* ───────── Type ───────── */
:root{font-feature-settings:"kern"}
h1,h2,h3,.mari-message-name,[data-mari-part="home-widget-title"]{font-family:var(--mari-font-heading);font-variation-settings:"SOFT" 100,"WONK" 0;letter-spacing:0}
.mari-message-name{font-weight:600;color:var(--maple-rose)}
[data-mari-part="message"] .mari-message-name{font-size:1.06rem!important}
[data-mari-part="home-widget-eyebrow"]{letter-spacing:.14em;font-weight:700}

/* ───────── Top bar ───────── */
[data-component="TopBar"]{border-bottom:0;box-shadow:0 4px 14px rgb(110 80 55/.10)}
:root[data-theme="dark"] [data-component="TopBar"]{box-shadow:0 4px 18px rgb(0 0 0/.35)}
[data-component="TopBar"] .ov-tab{box-shadow:0 1px 0 rgb(125 100 80/.10)}

/* ───────── Sidebars: linen paper ───────── */
.mari-sidebar,[data-component="RightPanelDesktop"],[data-component="OverhaulLibraryNav"],.mari-right-panel{
  background:var(--maple-paper) 0 0/256px 256px,var(--sidebar);
  border-color:var(--sidebar-border);
}
[data-chat-row]{border-radius:var(--maple-r-md);position:relative}
[data-chat-row][data-selected="true"]{background:var(--maple-blush);box-shadow:inset 3px 0 0 var(--primary)}

/* ───────── Shared control shapes ───────── */
.mari-chrome-control,.mari-chrome-field,input:not([type=range]):not([type=checkbox]):not([type=radio]),select{border-radius:999px}
textarea{border-radius:var(--maple-r-md)}

.ov-seg button.is-on{background:var(--accent);color:var(--accent-foreground);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--primary) 30%,transparent)}
.ov-switch:not(.is-on){background:color-mix(in srgb,var(--maple-muted) 26%,transparent)}
.ov-switch:not(.is-on) span{background:var(--maple-paper-c);box-shadow:0 1px 2px rgb(60 40 30/.2)}

/* ───────── Messages ───────── */
img[data-mari-part="backdrop"][data-default-background]{opacity:0}
[data-mari-part="avatar"]>div,[data-mari-part="avatar"] img{border-radius:999px!important;box-shadow:0 0 0 2px var(--maple-paper-c),0 0 0 3.5px color-mix(in srgb,var(--maple-sage) 60%,transparent)}

/* roleplay cards: paper + one sage stitch */
.mari-rp-bubble{
  background:var(--card);color:var(--maple-ink);border-width:0;border-radius:var(--maple-r-lg);
  box-shadow:var(--maple-shadow);-webkit-text-stroke:0!important;
}
:root .mari-rp-bubble,:root .mari-message-bubble{-webkit-text-stroke:0!important}
[data-mari-part="message"][data-message-role="assistant"] .mari-rp-bubble,
.mari-message-assistant .mari-rp-bubble{
  position:relative;
  background-image:none;
}
[data-mari-part="message"][data-message-role="assistant"] .mari-rp-bubble::before,
.mari-message-assistant .mari-rp-bubble::before{
  content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;
  border:10px solid transparent;border-image:var(--maple-stitch) 48 / 20px / 0 round;opacity:.9;
}
.mari-rp-bubble--user{background:var(--maple-blush);position:relative;overflow:visible!important}
.mari-rp-bubble--user::after{
  content:"";position:absolute;top:-6px;left:22px;width:92px;height:12px;pointer-events:none;
  background:url("theme:washi-tape.webp") center/100% 100% no-repeat;opacity:.95;
}
:root[data-theme="dark"] .mari-rp-bubble--user::after{opacity:.75}
[data-mari-part="message"][data-latest] .mari-rp-bubble{box-shadow:var(--maple-shadow-lg)}
[data-mari-part="message"][data-message-role="assistant"] .mari-rp-bubble,.mari-message-assistant .mari-rp-bubble{overflow:visible!important}
/* conversation: a paper page down the middle */
:root{--maple-col:rgb(251 246 236/.90)}
:root[data-theme="dark"]{--maple-col:rgb(43 35 32/.90)}
.mari-chat-area[data-chat-mode="conversation"] .mari-messages-scroll{
  background:linear-gradient(90deg,var(--maple-col) 0,var(--maple-col) min(860px,80%),transparent min(1080px,100%)) 0 0/100% 100% no-repeat!important;
}

/* message box */
[data-mari-part="composer"] .mari-chat-input-box,.mari-chat-input-box{
  background:var(--maple-paper-c);border:1px solid var(--border);border-radius:var(--maple-r-lg);box-shadow:var(--maple-shadow-lg);
}

/* ───────── Home ───────── */
[data-mari-part="home-widget"]{box-shadow:var(--maple-shadow);position:relative;padding:20px 22px}
[data-mari-part="home-widget"]::after{
  content:"";position:absolute;inset:3px;pointer-events:none;border-radius:calc(var(--mari-home-widget-radius) - 3px);
  border:10px solid transparent;border-image:var(--maple-stitch) 48 / 20px / 0 round;opacity:.65;
}

/* ───────── Pages (Settings, Library, editors) ───────── */
[data-component="CenterContent"][data-center-page] :is(.ov-card,.ov-panel){border-radius:var(--maple-r-lg)}

/* ───────── Panels: dialogs, menus, Ctrl+K, toasts ───────── */
[role="dialog"],[role="menu"],[role="listbox"],.mari-window,.mari-drawer{border-radius:var(--maple-r-lg);box-shadow:var(--maple-shadow-lg)}
[role="dialog"]:not([data-component="GlobalOmnibar"] *){background-image:var(--maple-paper);background-size:256px 256px}
[data-sonner-toast]{border-radius:var(--maple-r-md)!important;font-family:var(--mari-font-ui)!important;font-size:14px!important;
  background:var(--maple-paper) 0 0/256px 256px,var(--popover)!important;color:var(--foreground)!important;border:1px solid var(--border)!important;box-shadow:var(--maple-shadow-lg)!important}
[data-sonner-toast] [data-icon]{color:var(--maple-sage)!important}

/* ───────── Game ───────── */
[data-mari-part="message"][data-game-narration]{border-radius:var(--maple-r-lg)}
/* discord logo is white: ink it */
:root[data-theme="light"] img[src*="discord"]{filter:brightness(.4) sepia(.5) saturate(1.4)}

/* Reduce motion: no drifting fireflies (the app stops the layer anyway) */
@media (prefers-reduced-motion:reduce){:root{--mari-ambient-animation:none}}

/* phones: a placeholder that fits on one line */
@media (max-width:520px){:root{--mari-composer-placeholder:"write something…"}}
@media (max-width:900px),(hover:none){
  .mari-rp-bubble--user::after{top:auto;bottom:-6px;left:auto;right:18px;width:84px;height:11px}
}
@media (max-width:640px){
  [data-mari-part="message"][data-message-role="assistant"] .mari-rp-bubble,.mari-message-assistant .mari-rp-bubble{padding-left:18px;padding-right:18px}
}

/* readable on blush: your own name and time sit a shade deeper */
:root[data-theme="light"] [data-message-role="user"] .mari-message-name{color:#8A4743}
:root[data-theme="light"] [data-message-role="user"] [data-mari-part="time"]{color:#6B5A50}


/* ═════════ Round 5: v1.4 tokens instead of internal classes ═════════ */
:root{
  --mari-chat-wash:none;
  --mari-toast-font-size:15px;
  --mari-min-ui-text:12px;
  --mari-home-shortcut-size:15px;
  --mari-home-shortcut-desc-size:13.5px;
  --mari-ambient-placement:behind-cards;
  /* the top bar slides over Home when it shows: keep the greeting clear of it */
  --mari-home-hero-padding:calc(var(--mari-top-bar-height,44px) - .5rem) .25rem 1rem;
}
:root[data-theme="light"]{
  --mari-message-time:#76655A;
  --mari-lore-constant:#B9873A;--mari-lore-selective:#5F7B5A;--mari-lore-normal:#B9665F;
  --mari-user-avatar-image:url("theme:avatar-you-day.webp");
  --maple-char-avatar:url("theme:avatar-char-day.webp");
  --mari-chrome-accent:#A65D58;--mari-chrome-muted:#76655A;
  --mari-resource-accent:#A65D58;
  --mari-resource-characters:#E7B9B3;--mari-resource-personas:#C9D8C2;--mari-resource-lorebooks:#EBCF9E;
  --mari-resource-presets:#D8CBE0;--mari-resource-connections:#C9D8C2;--mari-resource-agents:#EBCF9E;
  --mari-resource-settings:#E5DACB;--mari-resource-backgrounds:#E7B9B3;--mari-resource-browser:#C9D8C2;
  --mari-ctrlk-conversation:#5F7B5A;--mari-ctrlk-roleplay:#A65D58;--mari-ctrlk-game:#8C6828;
  --mari-game-combat:#A65D58;--mari-game-combat-text:#FFFDF7;
  --mari-game-combat-bg:#A65D58;--mari-game-combat-bg-hover:#8E4E4A;--mari-game-combat-border:#8E4E4A;
  --mari-top-bar-plate-active:#F6E1DC;
  --mari-chat-header-bg:linear-gradient(to bottom,rgb(251 246 236/.94) 60%,rgb(251 246 236/0));
  --mari-home-widget-glow:rgb(217 168 91/.18);
  --mari-focus-frame:url("theme:focus-frame-day.webp") 96 / 48px round;
  --maple-stitch-c:#8FA98A;
}
:root[data-theme="dark"]{
  --mari-message-time:#BFAE9A;
  --mari-lore-constant:#E8B96A;--mari-lore-selective:#A9C79E;--mari-lore-normal:#E2877A;
  --mari-user-avatar-image:url("theme:avatar-you-night.webp");
  --maple-char-avatar:url("theme:avatar-char-night.webp");
  --mari-chrome-accent:#EBB0A7;--mari-chrome-muted:#CDBBA6;
  --mari-resource-accent:#EBB0A7;
  --mari-resource-characters:#EBB0A7;--mari-resource-personas:#B3C9A9;--mari-resource-lorebooks:#E8B96A;
  --mari-resource-presets:#C9B8DA;--mari-resource-connections:#B3C9A9;--mari-resource-agents:#E8B96A;
  --mari-resource-settings:#D9C8B4;--mari-resource-backgrounds:#EBB0A7;--mari-resource-browser:#B3C9A9;
  --mari-ctrlk-conversation:#B3C9A9;--mari-ctrlk-roleplay:#EBB0A7;--mari-ctrlk-game:#E8B96A;
  --mari-game-combat:#EBB0A7;--mari-game-combat-text:#2B2320;
  --mari-game-combat-bg:#EBB0A7;--mari-game-combat-bg-hover:#F2C6BE;--mari-game-combat-border:#F2C6BE;
  --mari-top-bar-plate-active:#5A3F3A;
  --mari-chat-header-bg:linear-gradient(to bottom,rgb(43 35 32/.94) 60%,rgb(43 35 32/0));
  --mari-home-widget-glow:rgb(232 185 106/.14);
  --mari-focus-frame:url("theme:focus-frame-night.webp") 96 / 48px round;
  --maple-stitch-c:#9DB394;
  /* lamplight pool and soft corners; the layer sits behind the cards, so it never dims the text */
  --mari-ambient:
    radial-gradient(ellipse 60% 50% at 18% 0%,rgb(232 185 106/.10),transparent 70%),
    radial-gradient(ellipse 120% 90% at 50% 45%,transparent 60%,rgb(18 11 8/.30) 100%);
}

/* the characters' empty avatar: a teacup on a saucer (yours is a daisy, via --mari-user-avatar-image) */
[data-mari-part="avatar-placeholder"][data-role="assistant"]{background:var(--maple-char-avatar) center/cover no-repeat!important;color:transparent!important}
[data-mari-part="avatar-placeholder"][data-role="assistant"]>svg{display:none}

/* focus frame: the same sage stitch, with the pressed sprig tucked into its corner.
   The newest reply, Ctrl+K, open dialogs and Home's Recent chats wear it; their own stitch steps aside. */
[data-mari-part="message"][data-latest] .mari-rp-bubble::before,
[data-home-widget-id="recent"] [data-mari-part="home-widget"]::after{display:none}
/* where the name sits above the card (phones, small tablets) the sprig would land on it: plain stitch there */
:root[data-mari-focus-frame] [data-mari-part="message"][data-latest]:has([data-mari-part="header"][data-placement="outside"]) .mari-rp-bubble{border-image:none}
[data-mari-part="message"][data-latest]:has([data-mari-part="header"][data-placement="outside"]) .mari-rp-bubble::before{display:block}

/* ═════════ Long replies: a book column, quieter dialogue, a pressed-lavender scene break ═════════ */
[data-mari-part="message"] .mari-rp-bubble{max-width:calc(var(--maple-measure) + 3rem)}
[data-mari-part="message"] .mari-rp-bubble strong:not([style]){color:var(--maple-ink);font-weight:800}
[data-mari-part="message"] .mari-rp-bubble em:not([style]){color:color-mix(in srgb,var(--maple-ink) 82%,var(--maple-sage))}
[data-mari-part="message"] .mari-rp-bubble ol,[data-mari-part="message"] .mari-rp-bubble ul{padding-left:1.7em;margin:.15em 0}
[data-mari-part="message"] .mari-rp-bubble li{margin:.25em 0;padding-left:.2em}
[data-mari-part="message"] .mari-rp-bubble li::marker{color:var(--maple-rose);font-family:var(--mari-font-heading);font-weight:600}
[data-mari-part="message"] .mari-rp-bubble hr,[data-mari-part="vn-text"] hr{
  border:0;height:28px;margin:10px 0 6px;opacity:.9;color:transparent;
  background:
    url("theme:rule-lavender.webp") center/auto 22px no-repeat,
    repeating-linear-gradient(90deg,var(--maple-stitch-c) 0 6px,transparent 6px 12px) left center/calc(50% - 60px) 1.5px no-repeat,
    repeating-linear-gradient(270deg,var(--maple-stitch-c) 0 6px,transparent 6px 12px) right center/calc(50% - 60px) 1.5px no-repeat;
}

/* the message box lines up with the reading column */
@media (min-width:1024px){[data-mari-part="composer"][data-composer="roleplay"] .mari-chat-input-box{max-width:calc(var(--maple-measure) + 9rem);margin-inline:auto}}

/* phones: the avatar tucks in beside the name instead of keeping a 55 px column down the whole reply */
@media (max-width:640px){
  [data-mari-part="message"].mari-roleplay-message-row{position:relative;gap:0}
  [data-mari-part="message"].mari-roleplay-message-row>[data-mari-part="avatar"]{position:absolute;top:-6px;z-index:2;height:auto!important;padding-top:0}
  [data-mari-part="message"].mari-roleplay-message-row>[data-mari-part="avatar"]~*{max-width:100%!important;width:100%;flex:1 1 auto}
  [data-mari-part="message"].mari-roleplay-message-row[data-message-role="assistant"]>[data-mari-part="avatar"]{left:6px}
  [data-mari-part="message"].mari-roleplay-message-row[data-message-role="user"]>[data-mari-part="avatar"]{right:6px}
  [data-mari-part="message"].mari-roleplay-message-row[data-message-role="assistant"] [data-mari-part="header"][data-placement="outside"]{padding-left:58px;min-height:34px}
  [data-mari-part="message"].mari-roleplay-message-row[data-message-role="user"] [data-mari-part="header"][data-placement="outside"]{padding-right:58px;min-height:34px}
}

/* conversation rows are lines, not cards: no frame around the newest one */
:root[data-mari-focus-frame] [data-chat-mode="conversation"] [data-mari-part="message"][data-latest]{border-image:none}
/* your empty avatar in conversations gets the daisy too */
[data-chat-mode="conversation"] [data-mari-part="avatar-placeholder"][data-role="user"]{background:var(--mari-user-avatar-image) center/cover no-repeat!important;color:transparent!important}
[data-chat-mode="conversation"] [data-mari-part="avatar-placeholder"][data-role="user"]>svg{display:none}
[data-chat-mode="conversation"] [data-mari-part="avatar"]>*{border-radius:999px;box-shadow:0 0 0 2px var(--maple-paper-c),0 0 0 3.5px color-mix(in srgb,var(--maple-sage) 60%,transparent)}


/* ═════════ Round 6: v1.5 tokens ═════════ */
:root[data-theme="light"]{
  --mari-message-actions:#76655A;--mari-swipe-counter:#8A4743;
  --mari-pinned-speaker-bg:linear-gradient(to bottom,#FFFDF7 calc(100% - .45rem),rgb(255 253 247/0));
  --mari-card-art-placeholder:url("theme:card-placeholder.webp") center 30%/cover no-repeat,#F7EBDD;
}
:root[data-theme="dark"]{
  --mari-message-actions:#BFAE9A;--mari-swipe-counter:#EBB0A7;
  --mari-pinned-speaker-bg:linear-gradient(to bottom,#3A302A calc(100% - .45rem),rgb(58 48 42/0));
  --mari-card-art-placeholder:url("theme:card-placeholder-night.webp") center 30%/cover no-repeat,#33261F;
}
/* the washi tape and the stitch step outside the card, so the card must not clip them */
:root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble{overflow:visible!important}
.mari-rp-bubble--user{--mari-pinned-speaker-bg:linear-gradient(to bottom,var(--maple-blush) calc(100% - .45rem),transparent)}
/* the pinned name keeps the stitch visible at the sides, and its soft edge falls below the name, not on the text */
:root{--mari-pinned-speaker-bleed:.3rem}
:root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head{padding-bottom:.45rem;margin-bottom:-.45rem}
/* dialogs and drawers: the plain stitch (the sprig would poke into the top bar above the Chat settings drawer) */
:root[data-theme="light"]{--maple-frame-plain:url("theme:focus-frame-plain-day.webp")}
:root[data-theme="dark"]{--maple-frame-plain:url("theme:focus-frame-plain-night.webp")}
:root[data-mari-focus-frame] [role="dialog"]{border-image-source:var(--maple-frame-plain)!important}

/* ═════════ VN display: the same journal card, one paragraph at a time ═════════ */
:root{--mari-vn-fade:2.25rem}
[data-roleplay-vn] .mari-chat-style-surface{
  position:relative;border:0;border-radius:var(--maple-r-lg);
  background:var(--maple-paper) 0 0/256px 256px,var(--maple-paper-c);box-shadow:var(--maple-shadow-lg);
}
[data-roleplay-vn] .mari-chat-style-surface::before{
  content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;
  border:10px solid transparent;border-image:var(--maple-stitch) 48 / 20px / 0 round;opacity:.9;
}
[data-roleplay-vn] .mari-chat-style-surface>*{position:relative}
[data-roleplay-vn] [data-mari-part="header"]{font-family:var(--mari-font-heading);font-size:1.06rem;font-weight:600;color:var(--maple-rose)}
[data-mari-part="vn-text"]{font-size:var(--mari-chat-font-size);color:var(--maple-ink);max-width:var(--mari-message-measure)}
[data-mari-part="vn-text"] strong:not([style]){color:var(--maple-ink);font-weight:800}
[data-mari-part="vn-counter"]{color:var(--maple-muted);opacity:1;font-family:var(--mari-font-heading);font-size:.8rem}
[data-mari-part="vn-nav"]{color:var(--maple-rose);border-radius:999px}
[data-roleplay-vn-navigation]{border-top:1.5px dashed color-mix(in srgb,var(--maple-stitch-c) 70%,transparent)!important;margin-inline:14px}
.mari-roleplay-vn-dialogue>[data-mari-part="avatar"]{border-radius:999px;border:0;box-shadow:0 0 0 2px var(--maple-paper-c),0 0 0 3.5px color-mix(in srgb,var(--maple-sage) 60%,transparent)}
/* phones: the VN portrait tucks in beside the name, so the paragraph gets the card's whole width */
@media (max-width:640px){
  .mari-roleplay-vn-dialogue{position:relative}
  .mari-roleplay-vn-dialogue>[data-mari-part="avatar"]{position:absolute;top:17px;left:19px;width:44px!important;height:44px!important;z-index:1}
  .mari-roleplay-vn-dialogue>[data-mari-part="avatar"]+*>[data-mari-part="header"]{padding-left:58px;min-height:48px;display:flex;align-items:center;margin-bottom:.35rem}
}

/* the new backdrops: still life on the counter, bottom right; portrait screens (phones, iPad Mini) get their own tall picture */
:root{--mari-app-backdrop-position:right bottom}
@media (orientation:portrait) and (max-width:1100px){
  :root[data-theme="light"]{--mari-app-backdrop:url("theme:backdrop-phone-day.webp")}
  :root[data-theme="dark"]{--mari-app-backdrop:url("theme:backdrop-phone-night.webp")}
  :root{--mari-app-backdrop-position:center bottom}
}
